/** Lat/lon to map units (equirectangular, longitude scaled for mid-latitudes). */
export function project(lat: number, lon: number): [number, number] {
  return [(lon - MAP.lon0) * MAP.kx * MAP.scale, (MAP.lat0 - lat) * MAP.scale];
}
